const xmlData = $input.first().json.data || $input.first().json.body || '';
const sourceName = $('W1: Source Tier Registry').item.json.name;
const sourceTier = $('W1: Source Tier Registry').item.json.tier;

// Fast regex extraction for XML/Atom items
const itemRegex = /<item[\s\S]*?<\/item>|<entry[\s\S]*?<\/entry>/gi;
const matches = xmlData.match(itemRegex) || [];

const items = [];
for (const block of matches.slice(0, 15)) {
  const titleMatch = block.match(/<title(?:[^>]*)>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/i);
  const linkMatch = block.match(/<link(?:[^>]*)>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/link>|<link[^>]*href=["']([^"']+)["']/i);
  const pubDateMatch = block.match(/<(?:pubDate|published|updated)>(.*?)<\/(?:pubDate|published|updated)>/i);

  const rawTitle = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, '').trim() : '';
  const rawUrl = linkMatch ? (linkMatch[1] || linkMatch[2] || '').trim() : '';

  if (rawTitle && rawUrl) {
    items.push({
      json: {
        source_name: sourceName,
        source_tier: sourceTier,
        headline: rawTitle,
        source_url: rawUrl,
        published_at: pubDateMatch ? pubDateMatch[1] : new Date().toISOString()
      }
    });
  }
}

return items;

