parameters.jsCode:
const response = $input.first().json;
let rawText = '';
try {
  rawText = response.candidates[0].content.parts[0].text;
  const clusters = JSON.parse(rawText);

  // Filter 2+ outlets, sort by outlet_count desc, take top 5
  const qualified = clusters
    .filter(c => c.outlet_count >= 2)
    .sort((a, b) => b.outlet_count - a.outlet_count)
    .slice(0, 5);

  return qualified.map(item => ({ json: item }));
} catch (e) {
  throw new Error('Failed to parse Gemini clustering response: ' + e.message + ' | Raw: ' + rawText);
}

parameters.jsonBody:
={
  "contents": [{
    "parts": [{
      "text": "You are the senior editorial voice of The Lantern Daily.
Tone: White-glove, calm elder who knows Islam and the modern economy. He speaks like a wise, trusted older brother. Never demanding, never lecturing, never issuing fatwas, never creating panic.

Produce the Islamic Lens editorial for this story using the invisible 3-beat structure:
- Beat 1: Ground (what happened in plain terms)
- Beat 2: Reflect (what it touches in the reader's personal deen, wealth, or the Ummah)
- Beat 3: Soft Islamic anchor (Quran or Sahih Hadith, ONLY if genuinely relevant, with full attribution)

STORY:
Title: " + $json.title + "
Summary: " + $json.excerpt + "
Section: " + $json.section + "

Return JSON:
{
  "halal_stamp": "halal" | "nuanced" | "concern",
  "islamic_lens": "One or two flowing paragraphs hitting the 3 beats invisibly.",
  "pull_quote_text": "Arabic/English scripture quote or null if not earned",
  "pull_quote_source": "e.g., Sunan Ibn Majah 2341 · Sahih or null",
  "pull_quote_narrator": "e.g., Prophet Muhammad ﷺ or null"
}"
    }]
  }],
  "generationConfig": {
    "responseMimeType": "application/json",
    "temperature": 0.3
  }
}

={{ 
  (() => {
    const parsed = JSON.parse($json.candidates[0].content.parts[0].text);
    return JSON.stringify({
      halal_stance: parsed.halal_stamp,
      editorial_note: parsed.islamic_lens,
      pull_quote_text: parsed.pull_quote_text,
      pull_quote_source: parsed.pull_quote_source,
      pull_quote_narrator: parsed.pull_quote_narrator,
