}}

={{ 
  (() => {
    const posts = $json;
    const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

    let htmlBody = `<p style="color: #B8922A; font-weight: bold;">بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ</p><p>The morning briefing for ${dateStr}. 5 stories moving the world, seen through the lens of clarity and sovereignty.</p><hr/>`;

    for (const post of posts) {
      htmlBody += `<h3>${post.title}</h3>`;
      htmlBody += `<p><em>Seen on: ${post.outlets ? post.outlets.join(' · ') : 'Major Outlets'}</em></p>`;
      htmlBody += `<p>${post.excerpt}</p>`;
      htmlBody += `<div style="border-left: 3px solid #B8922A; padding-left: 12px; margin: 16px 0;"><p><strong>Islamic Lens:</strong></p><p>${post.editorial_note || ''}</p></div>`;
      if (post.pull_quote_text) {
        htmlBody += `<blockquote style="background: #0D0F14; border: 1px solid #2A2D35; border-left: 4px solid #B8922A; padding: 12px; font-style: italic;">"${post.pull_quote_text}"<br/><span style="color: #B8922A; font-size: 0.85em;">— ${post.pull_quote_narrator || ''} (${post.pull_quote_source || ''})</span></blockquote>`;
      }
      htmlBody += `<p><a href="${post.source_url}">Read primary source →</a></p><hr/>`;
    }

    return JSON.stringify({
      title: `The Lantern Daily — ${dateStr}`,
      subtitle: '5 stories moving the world through the Islamic lens',
      content_html: htmlBody,
      status: 'draft',
      email_subject_line: `The Lantern Daily: ${posts[0]?.title || 'Morning Intelligence'}`
    });
  })()
}}
